   card('كتبنا', 'ماضي «كتب» مع نحن', 'نحن كتبنا الجدول على السبّورة.'), card('كتبوا', 'ماضي «كتب» مع هم', 'أحمد ويوسف وسامي كتبوا أسماءهم.'),
   card('تكتبين', 'مضارع «كتب» مع أنتِ', 'ليلى، أنتِ تكتبين بسرعة.'), card('يكتبون', 'مضارع «كتب» مع هم', 'الطلّاب يكتبون الآن.'),
